{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Topiramate oral bioavailability is high (>80%) in healthy volunteers, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Pipemidic acid absolute oral bioavailability averaged 93% versus intravenous administration in humans, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Gemcitabine oral bioavailability was estimated at 10% (range 5-17%) in patients, arguing for low F and contradicting the high prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer records support F >= 20%, including absolute oral bioavailability values of >80% and 93%; one high-transfer record (gemcitabine, 10%) argues for low F but is outweighed by the multiple positive records. Confidence is moderate due to this contradictory evidence and condition-specific measurements.",
  "evidence_gaps": [
    "One high-transfer contradictory record (gemcitabine, 10%) prevents a high-confidence prediction.",
    "Several positive records come from special populations or altered conditions, limiting direct transferability.",
    "Some positive records are qualitative or near-threshold, adding uncertainty to threshold classification."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

